<?php
session_start();
require_once __DIR__ . '/../includes/role_helpers.php';
requireAnyRole(['supplier']);
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/supplier_account.php';
$userId=(int)$_SESSION['user_id'];$profile=ensureSupplierProfile($conn,$userId,$_SESSION['name']??'Supplier');$supplierId=(int)$profile['id'];$message='';$success='';$selected=(int)($_GET['product_id']??$_POST['product_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
    $productId=(int)($_POST['product_id']??0);$quantity=(int)($_POST['quantity']??0);$note=trim($_POST['reason']??'Regular supplier delivery');
    if($productId<=0||$quantity<=0){$message='Select a product and enter a quantity greater than zero.';}else{
        try{
            $conn->begin_transaction();
            $stmt=$conn->prepare("SELECT id,product_name,stock_quantity FROM products WHERE id=? AND supplier_id=? AND status='active' FOR UPDATE");$stmt->bind_param('ii',$productId,$supplierId);$stmt->execute();$product=$stmt->get_result()->fetch_assoc();$stmt->close();
            if(!$product){throw new Exception('You can only supply products assigned to your Supplier account.');}
            $previous=(int)$product['stock_quantity'];$new=$previous+$quantity;
            $stmt=$conn->prepare("UPDATE products SET stock_quantity=? WHERE id=?");$stmt->bind_param('ii',$new,$productId);$stmt->execute();$stmt->close();
            $type='stock_in';$reason='Supplier supply: '.($note!==''?$note:'Regular delivery');
            $stmt=$conn->prepare("INSERT INTO inventory_transactions (product_id,transaction_type,quantity,reason,user_id,previous_stock,new_stock) VALUES (?,?,?,?,?,?,?)");$stmt->bind_param('isisiii',$productId,$type,$quantity,$reason,$userId,$previous,$new);$stmt->execute();$stmt->close();
            $action='Supplier Stock In';$description='Supplier added '.$quantity.' unit(s) to '.$product['product_name'].'. Previous stock: '.$previous.', New stock: '.$new.'.';
            $stmt=$conn->prepare("INSERT INTO activity_logs (user_id,action,description) VALUES (?,?,?)");$stmt->bind_param('iss',$userId,$action,$description);$stmt->execute();$stmt->close();
            $conn->commit();$success='Stock supplied successfully. '.$product['product_name'].' is now at '.$new.' unit(s).';$selected=$productId;
        }catch(Throwable $e){$conn->rollback();$message=$e->getMessage();}
    }
}
$stmt=$conn->prepare("SELECT id,product_name,stock_quantity,minimum_stock FROM products WHERE supplier_id=? AND status='active' ORDER BY product_name");$stmt->bind_param('i',$supplierId);$stmt->execute();$products=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$stmt=$conn->prepare("SELECT it.quantity,it.reason,it.transaction_date,p.product_name FROM inventory_transactions it JOIN products p ON p.id=it.product_id WHERE it.user_id=? AND it.transaction_type='stock_in' ORDER BY it.transaction_date DESC LIMIT 12");$stmt->bind_param('i',$userId);$stmt->execute();$history=$stmt->get_result();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Supply Stock</title><style>*{box-sizing:border-box;font-family:Arial,sans-serif}body{margin:0;min-height:100vh;color:#fff;background:#121426}.wrap{max-width:1000px;margin:auto;padding:34px 22px}.panel{background:#262740;border:1px solid #3c3e62;border-radius:16px;padding:24px;margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 180px;gap:14px}.group{margin:14px 0}.group label{display:block;font-weight:800;font-size:12px;margin-bottom:7px}.group input,.group select{width:100%;padding:12px;border-radius:9px;border:1px solid #4a4c71;background:#202036;color:#fff}.btn{border:0;border-radius:9px;padding:12px 18px;background:linear-gradient(135deg,#c06ceb,#5df09d);color:#17182c;font-weight:900;cursor:pointer}.alert{padding:12px 14px;border-radius:9px;margin:14px 0}.error{background:rgba(192,108,235,.12);border:1px solid rgba(192,108,235,.4)}.success{background:rgba(93,240,157,.12);border:1px solid rgba(93,240,157,.4)}table{width:100%;border-collapse:collapse}th,td{padding:11px;border-bottom:1px solid rgba(255,255,255,.08);text-align:left}th{background:#202036;color:#d7daea}@media(max-width:650px){.grid{grid-template-columns:1fr}.panel{overflow:auto}}</style></head><body><?php include __DIR__.'/nav.php'; ?><main class="wrap"><section class="panel"><h1 style="margin-top:0">Supply Stock</h1><p style="color:#b8bdd6">Stock can only be added to products assigned to your Supplier account.</p><?php if($message): ?><div class="alert error"><?php echo htmlspecialchars($message); ?></div><?php endif; ?><?php if($success): ?><div class="alert success"><?php echo htmlspecialchars($success); ?></div><?php endif; ?><form method="post"><div class="grid"><div class="group"><label>Product</label><select name="product_id" required><option value="">Select product</option><?php foreach($products as $p): ?><option value="<?php echo (int)$p['id']; ?>" <?php echo $selected===(int)$p['id']?'selected':''; ?>><?php echo htmlspecialchars($p['product_name']); ?> (Current: <?php echo (int)$p['stock_quantity']; ?>)</option><?php endforeach; ?></select></div><div class="group"><label>Quantity</label><input type="number" min="1" name="quantity" required></div></div><div class="group"><label>Delivery Note / Reason</label><input name="reason" maxlength="255" placeholder="Example: Weekly delivery"></div><button class="btn" type="submit">Add Supplied Stock</button></form></section><section class="panel"><h2 style="margin-top:0">Your Recent Supply History</h2><table><thead><tr><th>Product</th><th>Quantity</th><th>Reason</th><th>Date</th></tr></thead><tbody><?php if($history->num_rows): while($r=$history->fetch_assoc()): ?><tr><td><?php echo htmlspecialchars($r['product_name']); ?></td><td>+<?php echo (int)$r['quantity']; ?></td><td><?php echo htmlspecialchars($r['reason']); ?></td><td><?php echo htmlspecialchars($r['transaction_date']); ?></td></tr><?php endwhile; else: ?><tr><td colspan="4" style="text-align:center;color:#b8bdd6">No supply history yet.</td></tr><?php endif; ?></tbody></table></section></main></body></html>
